    if np.any(d < 0):
        raise ValueError("distance_matrix must contain non-negative distances")

    n = d.shape[0]
    if n == 0:
        return np.empty_like(d)

    mask = ~np.eye(n, dtype=bool)
    positive = d[mask & (d > 0)]
    eps = np.finfo(float).eps
    scale = np.median(positive) if positive.size else 1.0

    row_values = np.where(mask & (d > 0), d, np.nan)
    row_scale = np.nanmedian(row_values, axis=1)
    row_scale = np.where(np.isfinite(row_scale) & (row_scale > 0), row_scale, scale)

    local_scale = 0.5 * (row_scale[:, None] + row_scale[None, :])
    scores = np.exp(-d / (local_scale + eps)) / (d + eps)
    scores[~mask] = 0.0

    maximum = np.max(scores)
    if maximum > 0:
        scores /= maximum

